src:
loop 4
part rings {
  -- Rings
  loop 4
  pal(rainbow, frac(r*1.5 - t/2))
}
part stripes {
  -- Stripes
  loop 4
  size = 8 + a*24
  band = sin((px + py)/size - t/2)
  s = clamp(band*1.5 + 0.5, 0, 1)
  rgb(1, s, s)
}
-- the rings show only where the stripes are white
layer { gray(0.08) }
layer { rings(x, y, stripes.s) }

-- a: how far in the dark comes
d = len((x - 0.5)*2, (y - 0.5)*0.9)
layer multiply { gray(1 - smoothstep(1.1 - a*0.6, 1.3, d)) }

-- top bar: the hour (of 12); bottom bar: the minute
frame { hr = 104 + (hour % 12 + minute/60)/12*22; mn = 104 + minute/60*22 }
top = py > 3 and py < 6; bot = py > 0 and py < 3
bar = (top or bot) * (px >= 104) * (px < (top ? hr : mn))
layer multiply { gray(1 - (px >= 101) * (py < 8) * 0.8) }
layer { rgb(#ffbf4d, bar) }

loop 8
wave = sin(x*2 + t/8) + sin(y*1.5 - t/4) + sin(x*1.5 + y + t/8)
-- as bright as the GIF is there: dark stays dark
layer { hsv(wave/6 + t/8, 0.8, ul*1.2) }
layer add { gray(ul, 0.2) }
